--Alpha copy of Edinburgh Building height polygons
--This data is copyright the Ordnance Survey of Great Britain (2019)
--The data should not be used for other purposes than this teaching lab.

CREATE TABLE public.edinbuildings (
    id integer NOT NULL,
    geom public.geometry(MultiPolygon,27700),
    abshmin numeric,
    abshmax numeric,
    relhmax numeric
);



